import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class E {

	static long MOD=998244353;
	static long[] factorials, invFactorials;

	public static void main(String[] args) {
		precomputeFactorials();
		ScannerInput scanner=new ScannerInput();
		try {
		int n=scanner.readInt(), k=scanner.readInt();
		if (k==0) {
			System.out.println(factorials[n]);
			return;
		}
		if (k>=n) {
			System.out.println(0);
			return;
		}
		int remaining=n-k;
		long assignWays=calculatePower(remaining, n);
		long pickWays=calculateCombination(n, remaining);
		long total=mult(assignWays, pickWays);
		System.out.println(mult(total, 2));
		}
		catch(Throwable t) {
			System.out.println(0);
		}
	}

	static long calculatePower(int base, long exp) {
		long sum=0;
		for (int i=0; i<base; i++) {
			long term=fastPow(base-i, exp)*calculateCombination(base, i);
			if (i%2==0) {
				sum=add(sum, term);
			} else {
				sum=sub(sum, term);
			}
		}
		return sum;
	}

	static void precomputeFactorials() {
		factorials=new long[1_000_000];
		invFactorials=new long[1_000_000];
		factorials[0]=invFactorials[0]=1;
		for (int i=1; i<factorials.length; i++) factorials[i]=mul(factorials[i-1], i);
		invFactorials[factorials.length-1]=fastPow(factorials[factorials.length-1], MOD-2);
		for (int i=invFactorials.length-2; i>=0; i--) invFactorials[i]=mul(invFactorials[i+1], i+1);
	}

	static long calculateCombination(int n, int k) {
		return mul(factorials[n], mul(invFactorials[k], invFactorials[n-k]));
	}

	static long add(long a, long b) {
		return (a+b)%MOD;
	}

	static long sub(long a, long b) {
		return ((a-b)%MOD+MOD)%MOD;
	}

	static long mul(long a, long b) {
		return a*b%MOD;
	}

	static long fastPow(long base, long exp) {
		if (exp==0) return 1;
		long half=fastPow(base, exp/2);
		if (exp%2==0) return mul(half, half);
		return mul(half, mul(half, base));
	}

	static class ScannerInput {
		BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st=new StringTokenizer("");

		public String next() {
			while (!st.hasMoreElements())
				try {
					st=new StringTokenizer(br.readLine());
				} catch (IOException e) {
					e.printStackTrace();
				}
			return st.nextToken();
		}

		public int readInt() {
			return Integer.parseInt(next());
		}
	}
}
